// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        amount = bound(amount, 1, type(uint128).max);
        Reverter receiver = new Reverter();
        vm.deal(address(c), amount);
        uint256 before = address(c).balance;
        bool ok;
        try c.sendTo(address(receiver), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok || address(c).balance == before - amount);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
